def note_relevance(note):
    title = str(note.get('title', '')).lower()
    content = str(note.get('content', '')).lower()
    combined = title + '\n' + content
    score = 6 * int('workout' in title) + 3 * int('workout' in content) + 4 * int('today' in combined) + 4 * int(bool(current_date_text) and current_date_text in combined) + 2 * int(str(note.get('updated_at', '')).lower().startswith(current_date_text))
