def time_amounts_seconds(text):
    normalized = str(text).lower()
    for character in '\n\t,;:()[]{}-/':
        normalized = normalized.replace(character, ' ')
    tokens = normalized.split()
    amounts = []
    for index, unit_token in enumerate(tokens):
        unit = unit_token.strip('.')
        if index == 0 or not (unit.startswith('hour') or unit.startswith('hr') or unit.startswith('min') or unit.startswith('sec')):
            continue
        raw_amount = tokens[index - 1].strip('.')
        try:
            amount = float(raw_amount)
        except ValueError:
            amount = number_words.get(raw_amount)
        if amount is None:
            continue
        multiplier = 3600 if unit.startswith('hour') or unit.startswith('hr') else 60 if unit.startswith('min') else 1
        amounts.append(amount * multiplier)
    return amounts
